/* Amazon DNA — smile orange, squid ink navy, everything store density */
.theme-amazon-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.978 0.001 197.1);
  --surface-2: oklch(0.944 0.003 197.1);
  --fg: oklch(0.175 0.003 196.9);
  --fg-muted: oklch(0.461 0.004 197.0);
  --accent: oklch(0.772 0.174 64.6);
  --accent-fg: oklch(0.175 0.003 196.9);
  --accent-2: oklch(0.526 0.135 248.5);
  --line: oklch(0.882 0.004 197.1);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.772 0.174 64.6);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "PT Sans", sans-serif;
  --font-body: "PT Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.02em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-amazon-dna h1,
.theme-amazon-dna h2,
.theme-amazon-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-amazon-dna h1 { font-weight: 700; }
.theme-amazon-dna h1::after { content: ""; display: block; width: 4.5rem; height: 4px; margin-top: 0.5rem; background: var(--accent); border-radius: 999px 999px 999px 0; }
.theme-amazon-dna button { font-weight: 600; }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
